// Redis health check function
const timestamp = new Date().toISOString();
const startTime = Date.now();

// Redis connection test simulation
// In real implementation, this would use redis node
try {
    // Simulate Redis connection and basic operations
    const redisInfo = {
        host: 'horse_racing_redis_clean',
        port: 6379,
        database: 0
    };

    // Simulate Redis INFO command results
    const redisStats = {
        version: '7.0.0',
        uptime: Math.floor(Math.random() * 86400),
        connected_clients: Math.floor(Math.random() * 10) + 1,
        used_memory: '2.5MB',
        keyspace_hits: Math.floor(Math.random() * 10000),
        keyspace_misses: Math.floor(Math.random() * 1000),
        total_commands_processed: Math.floor(Math.random() * 50000)
    };

    const responseTime = Date.now() - startTime;

    const healthReport = {
        timestamp: timestamp,
        overall_status: responseTime < 100 ? 'healthy' : responseTime < 500 ? 'degraded' : 'down',
        redis_info: redisInfo,
        redis_stats: redisStats,
        connection_test: 'successful',
        response_time: responseTime + 'ms',
        cache_operations: {
            get_test: 'successful',
            set_test: 'successful',
            ping_test: 'PONG'
        }
    };

    msg.payload = healthReport;
    msg.statusCode = 200;

} catch (error) {
    const responseTime = Date.now() - startTime;

    msg.payload = {
        timestamp: timestamp,
        overall_status: 'down',
        error: error.message || 'Redis connection failed',
        response_time: responseTime + 'ms',
        connection_test: 'failed'
    };
    msg.statusCode = 503;
}

return msg;

// System status aggregation function
const timestamp = new Date().toISOString();
const startTime = Date.now();

// Prepare to call individual health check endpoints
// For now, we'll simulate the responses
// In a real implementation, we'd make HTTP requests to each service

const services = {
    database: {
        status: 'healthy',
        response_time: '9ms',
        last_check: timestamp,
        endpoint: '/database/health'
    },
    redis: {
        status: 'healthy',
        response_time: '3ms',
        last_check: timestamp,
        endpoint: '/redis/health'
    },
    containers: {
        status: 'healthy',
        running: 5,
        total: 5,
        last_check: timestamp,
        endpoint: '/containers/health'
    },
    web_app: {
        status: 'healthy',
        response_time: '45ms',
        last_check: timestamp,
        endpoint: '/web-app/health'
    },
    ml_trainer: {
        status: 'healthy',
        active_models: 3,
        last_training: '2 hours ago',
        last_check: timestamp
    }
};

// Calculate overall system status
const serviceStatuses = Object.values(services).map(s => s.status);
const hasDown = serviceStatuses.includes('down');
const hasDegraded = serviceStatuses.includes('degraded');

let overallStatus;
if (hasDown) {
    overallStatus = 'down';
} else if (hasDegraded) {
    overallStatus = 'degraded';
} else {
    overallStatus = 'healthy';
}

// Performance metrics
const metrics = {
    total_services: Object.keys(services).length,
    healthy_services: serviceStatuses.filter(s => s === 'healthy').length,
    degraded_services: serviceStatuses.filter(s => s === 'degraded').length,
    down_services: serviceStatuses.filter(s => s === 'down').length,
    uptime_percentage: 99.8,
    system_load: (Math.random() * 2).toFixed(2),
    memory_usage: Math.floor(Math.random() * 40 + 45) + '%',
    disk_usage: Math.floor(Math.random() * 30 + 60) + '%'
};

// Recent alerts/events
const events = [
    {
        timestamp: new Date(Date.now() - 300000).toISOString(),
        level: 'info',
        service: 'database',
        message: 'Database health check completed successfully'
    },
    {
        timestamp: new Date(Date.now() - 600000).toISOString(),
        level: 'info',
        service: 'redis',
        message: 'Redis cache cleared and optimized'
    },
    {
        timestamp: new Date(Date.now() - 900000).toISOString(),
        level: 'warning',
        service: 'ml_trainer',
        message: 'Model training took longer than expected (2.3s vs 1.5s avg)'
    }
];

const responseTime = Date.now() - startTime;

const systemStatus = {
    timestamp: timestamp,
    overall_status: overallStatus,
    services: services,
    metrics: metrics,
    recent_events: events,
    response_time: responseTime + 'ms',
    check_interval: '30s',
    next_check: new Date(Date.now() + 30000).toISOString()
};

msg.payload = systemStatus;
msg.statusCode = 200;
return msg;

// Container health check function
const timestamp = new Date().toISOString();
const startTime = Date.now();

// Simulate Docker container status checks
// In real implementation, this would use docker exec or API calls
const containers = {
    'horse_racing_postgres_clean': {
        status: 'running',
        health: 'healthy',
        uptime: '5 days',
        cpu_usage: (Math.random() * 30 + 5).toFixed(1) + '%',
        memory_usage: (Math.random() * 512 + 256).toFixed(0) + 'MB',
        network_io: '1.2MB/s',
        restart_count: 0,
        last_restart: null
    },
    'horse_racing_redis_clean': {
        status: 'running',
        health: 'healthy',
        uptime: '5 days',
        cpu_usage: (Math.random() * 10 + 2).toFixed(1) + '%',
        memory_usage: (Math.random() * 64 + 32).toFixed(0) + 'MB',
        network_io: '0.8MB/s',
        restart_count: 0,
        last_restart: null
    },
    'horse_racing_node_red': {
        status: 'running',
        health: 'healthy',
        uptime: '5 days',
        cpu_usage: (Math.random() * 20 + 10).toFixed(1) + '%',
        memory_usage: (Math.random() * 128 + 64).toFixed(0) + 'MB',
        network_io: '2.1MB/s',
        restart_count: 0,
        last_restart: null
    },
    'horse_racing_data_pipeline_clean': {
        status: 'running',
        health: 'healthy',
        uptime: '5 days',
        cpu_usage: (Math.random() * 40 + 15).toFixed(1) + '%',
        memory_usage: (Math.random() * 256 + 128).toFixed(0) + 'MB',
        network_io: '0.5MB/s',
        restart_count: 1,
        last_restart: '2 days ago'
    },
    'horse_racing_ml_trainer_clean': {
        status: 'running',
        health: 'healthy',
        uptime: '4 days',
        cpu_usage: (Math.random() * 60 + 20).toFixed(1) + '%',
        memory_usage: (Math.random() * 512 + 256).toFixed(0) + 'MB',
        network_io: '0.3MB/s',
        restart_count: 0,
        last_restart: null
    }
};

// Calculate summary statistics
const containerList = Object.entries(containers);
const runningContainers = containerList.filter(([name, info]) => info.status === 'running').length;
const healthyContainers = containerList.filter(([name, info]) => info.health === 'healthy').length;
const totalRestarts = containerList.reduce((sum, [name, info]) => sum + info.restart_count, 0);

// Calculate overall health
let overallHealth = 'healthy';
const unhealthyContainers = containerList.filter(([name, info]) => 
    info.status !== 'running' || info.health !== 'healthy'
);

if (unhealthyContainers.length > 0) {
    overallHealth = unhealthyContainers.length === containerList.length ? 'down' : 'degraded';
}

const responseTime = Date.now() - startTime;

const containerHealth = {
    timestamp: timestamp,
    overall_health: overallHealth,
    summary: {
        total_containers: containerList.length,
        running_containers: runningContainers,
        healthy_containers: healthyContainers,
        total_restarts: totalRestarts
    },
    containers: containers,
    network: {
        docker_network: 'horse_racing_network',
        subnet: '172.20.0.0/16',
        gateway: '172.20.0.1'
    },
    resources: {
        total_cpu_usage: containerList.reduce((sum, [name, info]) => {
            return sum + parseFloat(info.cpu_usage.replace('%', ''));
        }, 0).toFixed(1) + '%',
        total_memory_usage: containerList.reduce((sum, [name, info]) => {
            return sum + parseInt(info.memory_usage.replace('MB', ''));
        }, 0) + 'MB'
    },
    response_time: responseTime + 'ms'
};

msg.payload = containerHealth;
msg.statusCode = 200;
return msg;
